"""Every rounding rule of meterbill, in one place (see docs/rounding.md).

Nothing here reads or changes the decimal context: decimal rounding is done
with exact integer arithmetic, so the result never depends on process state.
"""

from __future__ import annotations

import math
from decimal import Decimal, InvalidOperation

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _coefficient(value: Decimal) -> int:
    return int(Decimal((0, value.as_tuple().digits, 0)))


def _make(sign: int, coefficient: int, exponent: int) -> Decimal:
    """The Decimal `coefficient * 10**exponent`, exactly, trailing zeros kept."""
    return Decimal((sign, Decimal(coefficient).as_tuple().digits, exponent))


def _check_step(step: Decimal) -> None:
    if not isinstance(step, Decimal):
        raise TypeError("step must be a Decimal")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be a positive decimal")


def _check_method(method: str) -> None:
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`; `method` decides ties and direction.

    The result has the exponent of `step` and the sign of `value` (also when it is zero).
    """
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    _check_method(method)
    _check_step(step)
    if value.is_snan():
        raise InvalidOperation("signaling NaN")
    if value.is_nan():
        return value
    if value.is_infinite():
        raise InvalidOperation("cannot round an infinite value")
    sign, _, exp = value.as_tuple()
    coef = _coefficient(value)
    _, _, step_exp = step.as_tuple()
    unit = _coefficient(step)
    if coef == 0:
        quotient = 0
    else:
        if exp >= step_exp:
            num, den = coef * 10 ** (exp - step_exp), unit
        else:
            num, den = coef, unit * 10 ** (step_exp - exp)
        quotient, remainder = divmod(num, den)
        twice = 2 * remainder
        if method == HALF_UP:
            if twice >= den:
                quotient += 1
        elif method == HALF_EVEN:
            if twice > den or (twice == den and quotient % 2 == 1):
                quotient += 1
    return _make(sign, quotient * unit, step_exp)


def _add(a: Decimal, b: Decimal) -> Decimal:
    """Exact sum of two finite decimals; a zero sum is negative only if both are."""
    if not (a.is_finite() and b.is_finite()):
        raise InvalidOperation("cannot add a non-finite value")
    sa, _, ea = a.as_tuple()
    sb, _, eb = b.as_tuple()
    exp = min(ea, eb)
    ia = _coefficient(a) * 10 ** (ea - exp) * (-1 if sa else 1)
    ib = _coefficient(b) * 10 ** (eb - exp) * (-1 if sb else 1)
    total = ia + ib
    if total == 0:
        return _make(1 if (sa and sb) else 0, 0, exp)
    return _make(1 if total < 0 else 0, abs(total), exp)


def _negate(a: Decimal) -> Decimal:
    sign, digits, exp = a.as_tuple()
    return Decimal((0 if sign else 1, digits, exp))


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """One part per amount, each a multiple of `step`, adding up to the rounded sum.

    Each amount is cut down to `step`; what the cuts lost against the sum
    rounded half up goes on the last amount that is not zero.
    """
    amounts = list(amounts)
    _check_step(step)
    parts = [round_amount(a, step, DOWN) for a in amounts]
    total = Decimal(0)
    for a in amounts:
        total = _add(total, a)
    whole = round_amount(total, step, HALF_UP)
    cut = _make(0, 0, step.as_tuple().exponent)
    for p in parts:
        cut = _add(cut, p)
    rest = _add(whole, _negate(cut))
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _add(parts[i], rest)
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
    """A float amount as the old customer system settled it (binary floating point)."""
    if isinstance(places, bool) or not isinstance(places, int):
        raise TypeError("places must be an int")
    if not 0 <= places <= 6:
        raise ValueError("places must be from 0 to 6")
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    """`value` written with `places` digits after the point (none for 0), rounded by `method`."""
    if isinstance(places, bool) or not isinstance(places, int):
        raise TypeError("places must be an int")
    if places < 0:
        raise ValueError("places must not be negative")
    _check_method(method)
    if isinstance(value, Decimal):
        if not value.is_finite():
            return str(value)
        rounded = round_amount(value, _make(0, 1, -places), method)
        sign, digits, _ = rounded.as_tuple()
        text = "".join(map(str, digits))
        if places:
            text = text.rjust(places + 1, "0")
            text = text[:-places] + "." + text[-places:]
        return ("-" if sign else "") + text
    if isinstance(value, (float, int)):
        if method != HALF_EVEN:
            raise ValueError("a float is only written half to even")
        return format(value, f".{places}f")
    raise TypeError("value must be a float or a Decimal")

"""The payable amount: some currencies settle in coins coarser than the cent."""

from __future__ import annotations

from decimal import Decimal

from meterbill import money


def payable(total: Decimal, rule: str) -> Decimal:
    """`rule` is the currency's `cash` entry in the tariff book."""
    if rule == "none":
        return total
    if rule == "whole":
        whole = money.round_amount(total, Decimal("1"), money.HALF_EVEN)
        # Decimal(round(total)) has always been an unsigned integer, also for -0.
        return Decimal(0) if whole == 0 else whole
    return money.round_amount(total, Decimal(rule), money.HALF_UP)

"""Credits from the old customer system, which stores them as binary floats."""

from __future__ import annotations

from decimal import Decimal

from meterbill import money


def settle(amount: float) -> float:
    """A credit as the old system settled it, to the cent."""
    return money.legacy_cents(amount)


def total(credits) -> Decimal:
    s = 0.0
    for c in credits:
        s += settle(c.amount)
    return Decimal(money.fixed(s, 2))


def line(credit) -> str:
    return money.fixed(settle(credit.amount), 2)

import json, os, random, subprocess, sys, tempfile, datetime

rnd = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
